function findSilent({workflows, executions, staleHours, now, workflowCursor, executionCursor}) {
  if (!Array.isArray(workflows) || !Array.isArray(executions)) throw new Error('Workflow and execution pages must be arrays');
  if (!Number.isFinite(staleHours) || staleHours <= 0) throw new Error('staleHours must be a positive number');
  const timestamp = new Date(now).getTime();
  if (!Number.isFinite(timestamp)) throw new Error('now must be a valid timestamp');
  const active = workflows.filter(workflow => workflow.active && !workflow.isArchived);
  const latest = new Map();
  for (const execution of executions) {
    const id = String(execution.workflowId);
    const started = new Date(execution.startedAt || execution.createdAt).getTime();
    if (!Number.isFinite(started)) continue;
    if (!latest.has(id) || started > latest.get(id)) latest.set(id, started);
  }
  const threshold = timestamp - staleHours * 3600000;
  const findings = [];
  for (const workflow of active) {
    const last = latest.get(String(workflow.id));
    if (last === undefined) findings.push({ workflow: workflow.name, workflowId: workflow.id, lastRun: null, hoursSilent: null, note: 'no execution in the window' });
    else if (last < threshold) findings.push({ workflow: workflow.name, workflowId: workflow.id, lastRun: new Date(last).toISOString(), hoursSilent: Math.round((timestamp - last) / 3600000), note: 'active but stalled' });
  }
  return { silent: findings.length, activeChecked: active.length, findings, workflowPageLimited: Boolean(workflowCursor), executionPageLimited: Boolean(executionCursor) };
}

const workflowPage=$('Get workflows').first().json;
const executionPage=$('Get executions').first().json;
return [{json:findSilent({workflows:workflowPage.data ?? [],executions:executionPage.data ?? [],staleHours:Number($('Configuration').first().json.staleHours),now:$now.toISO(),workflowCursor:workflowPage.nextCursor ?? null,executionCursor:executionPage.nextCursor ?? null})}];
